    out = [[bg for _ in range(w)] for _ in range(h)]
    candidates = []
    colors = set(v for row in grid for v in row if v != bg)
    for color in colors:
        # Dense rectangular patches are the intended objects; scattered cells are noise.
        for rh in range(2, h + 1):
            for rw in range(2, w + 1):
                area = rh * rw
                for r in range(h - rh + 1):
                    for c in range(w - rw + 1):
                        count = sum(grid[y][x] == color
                                    for y in range(r, r + rh)
                                    for x in range(c, c + rw))
                        if count >= 4 and count / area >= 0.65:
                            candidates.append((count, area, color, r, c, rh, rw))
    candidates.sort(reverse=True)
    claimed = [[False] * w for _ in range(h)]
    for count, area, color, r, c, rh, rw in candidates:
        cells = [(y, x) for y in range(r, r + rh) for x in range(c, c + rw)]
        if any(claimed[y][x] for y, x in cells):
            continue
        # Only take a patch if the observations inside it consistently indicate its color.
        if count / area < 0.65:
            continue
        for y, x in cells:
            claimed[y][x] = True
            out[y][x] = color
    return out
'''
